"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[372],{3498:e=>{e.exports=JSON.parse('{"functions":[{"name":"get","desc":"Returns the current value without yielding. On the server, errors if the player\'s saved data hasn\'t loaded yet.\\n\\nOn the client, errors if the value hasn\'t arrived yet. Call [Sencha.waitForReplicators] while loading, or use\\n[SavedReplicator:getAsync] or [SavedReplicator:observe] in code that may run earlier.","params":[{"name":"player","desc":"required on the server, left out on the client","lua_type":"Player?"}],"returns":[{"desc":"","lua_type":"T"}],"function_type":"method","source":{"line":104,"path":"src/Replication/Kinds/SavedReplicator/init.luau"}},{"name":"getAsync","desc":"Returns the current value, yielding until it\'s available. On the server, waits for the player\'s saved data to load.","params":[{"name":"player","desc":"required on the server, left out on the client","lua_type":"Player?"}],"returns":[{"desc":"","lua_type":"T"}],"function_type":"method","yields":true,"source":{"line":131,"path":"src/Replication/Kinds/SavedReplicator/init.luau"}},{"name":"onChanged","desc":"Calls `callback` when the value changes, not for the initial value. On the server it fires for any player whose value changes; on the client `player` is always the local player.\\n\\nOn the server, the change is sent to clients before `callback` runs, so anything it changes in response reaches\\nclients after the change that caused it.","params":[{"name":"callback","desc":"","lua_type":"(player: Player, newValue: T, oldValue: T) -> ()"}],"returns":[{"desc":"","lua_type":"Disconnect"}],"function_type":"method","source":{"line":154,"path":"src/Replication/Kinds/SavedReplicator/init.luau"}},{"name":"observe","desc":"Calls `callback` with the current value right away if it has arrived (otherwise when it arrives), then on\\nevery change.","params":[{"name":"callback","desc":"","lua_type":"(value: T) -> ()"}],"returns":[{"desc":"","lua_type":"Disconnect"}],"function_type":"method","realm":["Client"],"source":{"line":178,"path":"src/Replication/Kinds/SavedReplicator/init.luau"}},{"name":"onUpdateReceived","desc":"Calls `callback` for each patch received, after the value is updated. Only replicators with an incremental\\nconfig receive patches; calling this on one without errors.\\n\\nFull values (the first value, a `set`, or a resync) only fire [SavedReplicator:onChanged], so use that to see every\\nchange.","params":[{"name":"callback","desc":"","lua_type":"(newValue: T, oldValue: T, patch: P) -> ()"}],"returns":[{"desc":"","lua_type":"Disconnect"}],"function_type":"method","realm":["Client"],"source":{"line":197,"path":"src/Replication/Kinds/SavedReplicator/init.luau"}},{"name":"getObservable","desc":"Returns an [ObservableValue](https://jdevon.github.io/observable-value/) that follows the replicated value,\\nfor code that works with ObservableValues, like the\\n[ReactObservableValue](https://github.com/JDevon/react-observable-value) hooks. Calling it again returns the same\\none. Setting it doesn\'t change the replicated value. Errors if the value hasn\'t arrived yet.\\n\\n```lua\\nlocal research = ReactObservableValue.useObservableValue(ResearchNetwork.researchReplicator:getObservable())\\n```","params":[],"returns":[{"desc":"","lua_type":"ObservableValue<T>"}],"function_type":"method","realm":["Client"],"source":{"line":221,"path":"src/Replication/Kinds/SavedReplicator/init.luau"}},{"name":"isLoaded","desc":"Returns whether the value has arrived from the server.","params":[],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"method","realm":["Client"],"source":{"line":235,"path":"src/Replication/Kinds/SavedReplicator/init.luau"}}],"properties":[],"types":[],"name":"SavedReplicator","desc":"A read-only view of part of a player\'s saved data, created with [SavedSource:replicator]. Its value is sent\\nonly to the player it belongs to.\\n\\nTo change it, update the saved data; the change replicates when the store calls [SavedSource:replicateChanges].\\nThis keeps one write path, so an update to several fields at once stays atomic.","source":{"line":22,"path":"src/Replication/Kinds/SavedReplicator/init.luau"}}')}}]);